```ts
/**
 * Tap every WebSocket instance: count outbound envelopes by type and record
 * close codes. Must be injected via context.addInitScript (before the page's
 * session code runs — if you patch after goto, you miss the first
 * connection, and pre-fix the 4009 lands before the tap exists).
 */
function tapNet(): void {
  const w = window as unknown as {
    __NET__?: {
      sent: { input: number; fire: number; total: number };
      stamps: { input: number[]; fire: number[] };
      closes: Array<{ code: number; reason: string }>;
    };
  };
  w.__NET__ = {
    sent: { input: 0, fire: 0, total: 0 },
    stamps: { input: [], fire: [] },
    closes: [],
  };
  const Orig = window.WebSocket;
  window.WebSocket = class extends Orig {
    constructor(...args: ConstructorParameters<typeof Orig>) {
      super(...args);
      const net = (window as typeof w).__NET__!;
      const origSend = this.send.bind(this);
      this.send = (data: string | ArrayBufferLike | Blob | ArrayBufferView): void => {
        try {
          const m = JSON.parse(String(data)) as { type?: string };
          net.sent.total += 1;
          if (m.type === 'input') {
            net.sent.input += 1;
            net.stamps.input.push(Date.now());
          } else if (m.type === 'fire') {
            net.sent.fire += 1;
            net.stamps.fire.push(Date.now());
