5. NET TAP via `context.addInitScript` (must run before the page code): wrap the WebSocket prototype to count sent messages by type + record closes. Plus the ship update tap (the `__t91` pattern).

NET tap:
```js
function tapNet(): void {
  const w = window as any;
  w.__NET__ = { sent: { input: 0, fire: 0, total: 0 }, closes: [] as {code:number; reason:string}[] };
  const Orig = window.WebSocket;
  window.WebSocket = class extends Orig {
    constructor(...args) {
      super(...args);
      const origSend = this.send.bind(this);
      this.send = (data: string) => {
        try {
          const m = JSON.parse(data);
          w.__NET__.sent.total++;
          if (m.type === 'input') w.__NET__.sent.input++;
          else if (m.type === 'fire') w.__NET__.sent.fire++;
        } catch { /* ignore */ }
        origSend(data);
      };
      this.addEventListener('close', (ev) => {
        w.__NET__.closes.push({ code: ev.code, reason: ev.reason });
      });
    }
  };
}
```

6. Reconnect watcher: poll `page.locator('text=reconnecting').count()` every 500ms during the jitter window, collecting hit counts.

